function FPALIVE(i) local aa,P = FPAA,FPP local e = P(aa(FPD, (i or FPI)*4)); if not e then return false end return P(aa(e, 0x348)) == "00000001" end function FPUNITALIVE(i) local aa,P = FPAA,FPP local e = P(aa(FPD, (i or FPI)*4)); if not e then return 0 end local u = P(aa(e, 0x1EC)); if not u or u == "00000000" then return 0 end return tonumber(ESE_ReadInt(aa(u, 0x178))) or 0 end function FPPICK(apply) local aa,P = FPAA,FPP local ex=tonumber(ESE_ReadFloat(aa(FPCAM,0x08))) local ey=tonumber(ESE_ReadFloat(aa(FPCAM,0x0C))) local ez=tonumber(ESE_ReadFloat(aa(FPCAM,0x10))) local fx=tonumber(ESE_ReadFloat(aa(FPCAM,0x60))) local fy=tonumber(ESE_ReadFloat(aa(FPCAM,0x64))) local fz=tonumber(ESE_ReadFloat(aa(FPCAM,0x68))) if not ex or not fx then return "no camera" end local best,bang,bd,bu = nil,1e9,0,nil for i=0,FPCNT-1 do local e=P(aa(FPD,i*4)) if e then local x=tonumber(ESE_ReadFloat(aa(e,0x48))) local y=tonumber(ESE_ReadFloat(aa(e,0x4C))) local z=tonumber(ESE_ReadFloat(aa(e,0x50))) local liveok = (P(aa(e,0x348)) == "00000001") or FPPICKDEAD if liveok and x and y and z and x==x and math.abs(x)<2000 then local dx,dy,dz = x-ex, (y+0.9)-ey, z-ez local d=math.sqrt(dx*dx+dy*dy+dz*dz) if d>0.5 then local dot=(dx*fx+dy*fy+dz*fz)/d if dot>0 then local ang=math.acos(math.min(dot,1)) local score=ang + d*0.0004 if score<bang then bang=score best=i bd=d bu=P(aa(e,0x1EC)) end end end end end end if not best then return "nothing in front of the camera" end if apply then FPI=best for k=1,20 do FPSTEP() end end return string.format("nearest LIVING man to crosshair: %d  dist=%.1f m  unit=%s%s", best, bd, tostring(bu), apply and "  -> HOOKED" or "") end return "FPPICK loaded"